import React from 'react';
import videoback from "../video/backvideo.mp4";
function intro(){
    return (
        <video autoPlay loop muted className="bottom-0 opacity-75 object-cover"  style={{
          width: "100%",
          height: "100vh",
          objectFit: "cover",
          zIndex: 0,
        }} >
        <source src={videoback} type="video/mp4" />
      </video>
    )
}

export default intro;


