import React, { useState } from "react";
import Alert from "../components/alert.js";
import Intro from '../components/intro.js';
import emailjs from '@emailjs/browser';

const Contattaci = () => {
  const [formData, setFormData] = useState({
    email: "",
    message: "",
  });

  const [isEmailSent, setIsEmailSent] = useState(false); // Definisci e inizializza la variabile isEmailSent

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const sendEmail = (e) => {
    e.preventDefault();
    const form = document.getElementById('myForm');

    if (form) {
      emailjs.sendForm(process.env.REACT_APP_SERVICE_ID, process.env.REACT_APP_TEMPLATE_ID, form, process.env.REACT_APP_PUBLIC_KEY)
        .then((response) => {
          console.log('Email inviata con successo', response);
          setIsEmailSent(true); // Imposta isEmailSent a true quando l'email è stata inviata
        })
        .catch((error) => {
          console.error('Errore nell\'invio dell\'email', error);
        });
    } else {
      console.error('Il formulario con l\'ID "myForm" non è stato trovato.');
    }
  };

  return (
    <div className="position-relative">
      <Intro />

      <form className="position-absolute top-50 start-50 translate-middle w-50  mt-3 pt-5 bt-5" id="myForm" onSubmit={sendEmail}>
        <div className="mb-3">
          <label htmlFor="email" className="form-label text-light rounded-4 d-flex justify-content-center">Email</label>
          <input
            type="email"
            className="form-control"
            id="email"
            name="email_from"
            value={formData.email_from}
            onChange={handleInputChange}
            required
          />
        </div>

        <div className="mb-3">
          <label htmlFor="message" className="form-label text-light rounded-4 d-flex justify-content-center">Messaggio</label>
          <textarea
            className="form-control"
            id="message"
            name="message"
            value={formData.message}
            onChange={handleInputChange}
            rows="4"
            required
          ></textarea>
        </div>
        <div className="d-flex justify-content-center">
          <button type="submit" variant='contained' className="btn btn-primary">Invia</button>

        </div>
        {isEmailSent && <Alert message="Email inviata !" />}

      </form>

    </div>
  );
};

export default Contattaci;
