import React, { useState } from "react";
import { Link } from "react-router-dom";

function Navbar() {
  const [isOpen, setIsOpen] = useState(false);

  const toggleMenu = () => {
    setIsOpen(!isOpen);
  };

  const closeMenu = () => {
    if (isOpen) {
      setIsOpen(false);
    }
  };

  return (
    <nav className="navbar navbar-expand-lg navbar-dark newfont">
      <button
        className={`navbar-toggler ${isOpen ? "collapsed" : ""}`}
        type="button"
        data-bs-toggle="collapse"
        data-bs-target="#navbarNavAltMarkup"
        aria-controls="navbarNavAltMarkup"
        aria-expanded={isOpen ? "true" : "false"}
        aria-label="Toggle navigation"
        onClick={toggleMenu}
      >
        <span className="navbar-toggler-icon"></span>
      </button>
      <div
        className={`collapse navbar-collapse justify-content-center ${isOpen ? "show" : ""}`}
        id="navbarNavAltMarkup"
      >
        <div className="navbar-nav">
          <Link to="/" className="nav-item nav-link active text-white" onClick={closeMenu}>
            HOME
          </Link>
          <Link to="/contattaci" className="nav-item nav-link active text-white" onClick={closeMenu}>
            CONTATTACI
          </Link>
          <Link to="/invendita" className="nav-item nav-link active text-white" onClick={closeMenu}>
            IN VENDITA
          </Link>
        </div>
      </div>
    </nav>
  );
}

export default Navbar;
