import React from 'react';
import 'bootstrap/dist/css/bootstrap.css'; // Importa il CSS di Bootstrap
import 'bootstrap-icons/font/bootstrap-icons.css'; // Importa il CSS delle icone Bootstrap
import { Link} from "react-router-dom";

function Footer()  {
  return (
    <footer className="d-flex flex-wrap justify-content-between text-light align-items-center mt-5 pb-5 pr-5 border-top bg-black">
    <div className="col-md-4 d-flex align-items-center ">

      <span className="mb-3 mb-md-0 text-light ps-2 mt-3">© PortfolioImmobiliare, Inc</span>
    </div>
    <ul className="nav col-md-4 justify-content-center list-unstyled d-flex pe-4 pt-3">
    <li className="ms-3"> </li>

    <li className="ms-3">
    <Link to="/">
      <i className="bi bi-twitter text-light"></i> {/* Icona Twitter */}
    </Link>
  </li>
  <li className="ms-3">
    <Link to="/">
      <i className="bi bi-instagram text-light"></i> {/* Icona Instagram */}
    </Link>
  </li>
  <li className="ms-3">
    <Link to="">
      <i className="bi bi-facebook text-light"></i> {/* Icona Facebook */}
    </Link>
    </li>


    </ul>

  </footer>
  );
}

export default Footer;
