import React, { useState, useEffect } from "react";
import './style.css';
import Records from '../record.json';
import 'bootstrap/dist/css/bootstrap.min.css';

function Invendita() {
    const [allRecords, setAllRecords] = useState([]);
    const [filteredRecords, setFilteredRecords] = useState([]);
    const [filters, setFilters] = useState({
        tipo: 'all',
        minPrezzo: 0,
        maxPrezzo: 0,
    });

    useEffect(() => {
        // Inizializza sia tutti i record che quelli filtrati con i dati iniziali
        setAllRecords(Records);
        setFilteredRecords(Records);

        const maxPrezzo = Math.max(...Records.map(record => parseFloat(record.prezzo)));
        setFilters((prevFilters) => ({
            ...prevFilters,
            maxPrezzo: maxPrezzo,
        })); // Imposta il prezzo massimo
    }, []);

    const handleTipoChange = (event) => {
        const tipo = event.target.value;
        setFilters({ ...filters, tipo });

        updateFilteredRecords({ ...filters, tipo });
    };

    const handleMinPrezzoChange = (event) => {
        const minPrezzo = parseFloat(event.target.value);
        setFilters({ ...filters, minPrezzo });

        updateFilteredRecords({ ...filters, minPrezzo });
    };

    const handleMaxPrezzoChange = (event) => {
        const maxPrezzo = parseFloat(event.target.value);
        setFilters({ ...filters, maxPrezzo });

        updateFilteredRecords({ ...filters, maxPrezzo });
    };

    const uniqueTipi = [...new Set(allRecords.map(record => record.tipo))];

    const updateFilteredRecords = (filters) => {
        const { tipo, minPrezzo, maxPrezzo } = filters;
        const filtered = allRecords.filter(record => {
            if (tipo !== 'all' && record.tipo !== tipo) {
                return false;
            }

            const prezzo = parseFloat(record.prezzo);
            if (prezzo < minPrezzo || prezzo > maxPrezzo) {
                return false;
            }

            return true;
        });

        setFilteredRecords(filtered);
    };

    return (
        <div className="">
            <div className="d-flex">
                <div className="container-fluid bg-black" style={{ height: "15vh" }}></div>
            </div>

            <div className="container-fluid">
                <div className="row mt-5">
                    <div className="col-3 bg-dark text-light mt-2 ">
                            <div className="border border-light px-1 py-1">
                        <h5 className="text-white  "> Filtri</h5>
                        <div className="form-group ">
                            <label htmlFor="tipoSelect">Tipo di casa</label>
                            <select
                                className="form-control"
                                id="tipoSelect"
                                value={filters.tipo}
                                onChange={handleTipoChange}
                            >
                                <option value="all">Tutti</option>
                                {uniqueTipi.map(tipo => (
                                    <option key={tipo} value={tipo}>
                                        {tipo}
                                    </option>
                                ))}
                            </select>
                        </div>
                        <div className="form-group">
                            <label htmlFor="minPrezzo">Prezzo Minimo</label>
                            <input
                                type="number"
                                className="form-control"
                                id="minPrezzo"
                                value={filters.minPrezzo}
                                onChange={handleMinPrezzoChange}
                            />
                        </div>
                        <div className="form-group">
                            <label htmlFor="maxPrezzo">Prezzo Massimo</label>
                            <input
                                type="number"
                                className="form-control"
                                id="maxPrezzo"
                                value={filters.maxPrezzo}
                                onChange={handleMaxPrezzoChange}
                            />
                        </div>
                    </div>
                                    </div>
                    <div className="col-9">
    {filteredRecords.map(record => (
        <div className="col-12 bg-light text-light bg-dark text-center mt-2 pt-2 border border-light" key={record.id}>
            <div>{record.title}</div>
            <div>{record.tipo}</div>
            <div>€{record.prezzo}.00</div>
            <img className="img-fluid "
                src={process.env.PUBLIC_URL + `/image/buildingimages/${record.id}.jpg`}
                alt={record.title}/>
                            <div className="pb-4 ">Codice riferimento:{record.id}</div>

        </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
}

export default Invendita;
