import React, { useState, useEffect } from "react";
import './style.css';

function Carousel() {
  const [isFadingIn, setIsFadingIn] = useState(false);

  useEffect(() => {
    setIsFadingIn(true);
  }, []);

  return (
    <div id="carouselExample" className="carousel slide d-flex bg-black container-fluid p-0" style={{ zIndex: 1, }}>
      <div className="carousel-inner mt-5 pt-5 bt-5 mb-5 position-relative">
        <div
          className={`position-absolute  z-1       fade-in ${isFadingIn ? "active" : ""}`}
          style={{ top: "40%", left: "30%" }} 
        > 
          <h2>"Case che parlano, clienti che ascoltano."... </h2>
        </div>
        <div className="carousel-item active">
          <img
            src="https://www.chiusano.com/public/file/fl-20191016185122.jpg"
            className="d-block w-100 img-fluid"
            alt="..."
            style={{ maxHeight: "100vh" }}
          />
        </div>
        <div className="carousel-item">
          <img
            src="https://www.chiusano.com/public/file/fl-20210913145121.jpg"
            className="d-block w-100 img-fluid"
            alt="..."
            style={{ maxHeight: "100vh" }}
          />
        </div>
        <div className="carousel-item">
          <img
            src="https://www.chiusano.com/public/file/fl-20191017093723.jpg"
            className="d-block w-100 img-fluid"
            alt="..."
            style={{ maxHeight: "100vh" }}
          />
        </div>
      </div>
      <button
        className="carousel-control-prev"
        type="button"
        data-bs-target="#carouselExample"
        data-bs-slide="prev"
      >
        <span className="carousel-control-prev-icon No-opacity" aria-hidden="true"></span>
        <span className="visually-hidden">Previous</span>
      </button>
      <button
        className="carousel-control-next"
        type="button"
        data-bs-target="#carouselExample"
        data-bs-slide="next"
      >
        <span className="carousel-control-next-icon No-opacity" ariahidden="true"></span>
        <span className="visually-hidden">Next</span>
      </button>
    </div>
  );
}

export default Carousel;
